import * as welcomeForm from '/welcome-form.js';
import './direction-entry.js';
import {calendarHTML,calendarStyles,meetingDate} from '/meeting-calendar.js';
import * as preventionEditor from '/prevention-editor.js';
import {displayDocument} from '/document-reader.js';
import * as equipmentTraining from '/equipment-training.js';
import * as inspectionGrid from '/inspection-grid.js';
import * as incidentReport from '/incident-report.js';
import * as incidentOrganisation from '/incident-groups.js';
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kinds={training:{name:'Formations',single:'Formation',icon:'FO',description:'Les activités de formation reliées aux fiches employés et leurs preuves.',fields:[['trainer','Formateur / organisme'],['verification','Comment la compréhension ou la compétence a été vérifiée'],['reference','Procédure ou document utilisé']],hint:'Consigne la formation réellement donnée. La date, le formateur et la vérification sont nécessaires pour la marquer réalisée.'},equipment:{name:'Équipements',single:'Équipement',icon:'ÉQ',description:'Manuels, procédures, entretien et vérifications de vos équipements.',fields:[['model','Fabricant et modèle'],['serial','Numéro de série / identification'],['location','Emplacement'],['procedure','Méthode d’utilisation, nettoyage et maîtrise des énergies'],['verification','Vérifications et entretien']],hint:'Rattache les manuels et les procédures applicables à cet équipement. Un document joint ne remplace pas une vérification sur place.'},incident:{name:'Incidents et enquêtes',single:'Incident / enquête',icon:'IN',description:'Les faits rapportés, les vérifications, les conclusions et les mesures prises.',fields:[['location','Lieu et équipement'],['reportedFacts','Faits observés ou rapportés · préciser par qui'],['analysis','Analyse des causes et facteurs contributifs'],['verification','Vérifications et mesures prises'],['outcome','Conclusions et suivi']],hint:'Sépare les faits observés, les déclarations et les conclusions vérifiées. Conserve les documents médicaux dans le dossier confidentiel approprié.'},meeting:{name:'Comité et rencontres',single:'Rencontre SST',icon:'CO',description:'Ordres du jour, comptes rendus, décisions et suivis du comité.',fields:[['meetingType','Type de rencontre'],['participants','Participants et fonctions'],['location','Lieu'],['findings','Points discutés'],['outcome','Décisions et actions convenues']],hint:'Ajoute le compte rendu original et lie les correctifs aux décisions de la rencontre.'},inspection:{name:'Inspections et visites',single:'Inspection / visite',icon:'VI',description:'Visites, inspections du magasin, constats et pièces à présenter.',fields:[['location','Zone ou organisme'],['reference','Référence de l’avis / du rapport'],['findings','Points à préparer ou constats relevés'],['verification','Vérifications effectuées'],['outcome','Suites à donner']],hint:'Distingue les pièces à réunir des constats effectivement relevés pendant l’inspection.'},action:{name:'Correctifs et suivis',single:'Correctif',icon:'AC',description:'Une mesure, un responsable, une échéance et une vérification de réalisation.',fields:[['procedure','Mesure à réaliser'],['verification','Vérification de l’efficacité / de la réalisation'],['outcome','Résultat obtenu']],hint:'Précise ce qui doit être fait. La date de réalisation et la vérification sont nécessaires pour fermer le correctif.'},document:{name:'Documents de référence',single:'Document de référence',icon:'DO',description:'Classe les formulaires, procédures et documents de référence du magasin.',fields:[['reference','Version / référence'],['procedure','Usage prévu et consignes de conservation']],hint:'Conserve l’original comme pièce jointe. Utilise un titre et une version faciles à retrouver.'}};
const statusLabels=(kind)=>kind==='document'?{draft:'À vérifier / compléter',open:'Référence disponible',progress:'À réviser',done:'Classé / validé'}:kind==='equipment'?{draft:'À compléter',open:'En service',progress:'À vérifier / entretien',done:'Hors service'}:kind==='incident'?{draft:'À vérifier',progress:'En cours',done:'Consolidé'}:kind==='action'?{draft:'À définir',open:'À réaliser',progress:'En cours',done:'Réalisé et vérifié'}:{draft:'À compléter',open:'Prévu / à préparer',progress:'En cours',done:'Réalisé / consigné'};
const views={dashboard:['Vue d’ensemble','LE POINT SUR LA PRÉVENTION','Les dossiers, les preuves disponibles et les prochaines étapes.','VE'],employees:['Employés','UN SEUL RÉPERTOIRE','Fiches issues de Quarts Service et des horaires des départements.','EM'],...Object.fromEntries(Object.entries(kinds).map(([k,v])=>[k,[v.name,'LE SUIVI SST DU MAGASIN',v.description,v.icon]])),equipment_training:['Formation aux équipements','REGISTRE PAR TÂCHE','Affectations, pièces, témoignages, formations et observations pratiques.','FE'],inspection_grid:['Grille d’inspection','INSPECTION SST SUR LE TERRAIN','La grille du magasin à remplir, enregistrer et reprendre sur iPad.','GI'],prevention:['Programme de prévention','LE PROGRAMME DU MAGASIN','Le programme de prévention, ses versions et les documents originaux.','PP'],sobeys:['Ressources Sobeys','MODÈLES ET MÉTHODES','Les documents de la mutuelle, leurs versions et leurs liens sources.','SO'],task_analysis:['Analyse des tâches','PRÉVENTION PAR POSTE','Les analyses des tâches, les risques et les mesures de prévention par département.','AT'],documents:['Bibliothèque de preuves','LES ORIGINAUX, AU BON ENDROIT','Photos, PDF et documents joints aux dossiers.','PI'],journal:['Historique des saisies','LA TRAÇABILITÉ DES DOSSIERS','Les créations, les corrections et les archives sont horodatées.','HI']};
const iso=v=>v?String(v).slice(0,10):'';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const date=v=>v?new Intl.DateTimeFormat('fr-CA',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(iso(v)+'T12:00:00Z')):'Non précisée';
const stamp=v=>new Intl.DateTimeFormat('fr-CA',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Toronto'}).format(new Date(v));
const bytes=n=>n>=1048576?(n/1048576).toFixed(1)+' Mo':Math.max(1,Math.round(n/1024))+' Ko';
let state={records:[],documents:[],employees:[],departments:[]},view='dashboard',editing=null,detailId=null,employeeKey=null;
let detailSequence=0,loading=false;
incidentOrganisation.configure({getState:()=>state,api,refresh:load,notice,openRecord:openDetail,person:r=>person(r),date});
welcomeForm.configure({getState:()=>state,save:body=>api('records',body),afterSave:async id=>{await load();return state.records.find(r=>r.id===id);}});
incidentReport.configure({getState:()=>state,save:body=>api('records',body),afterSave:async id=>{await load();notice('Rapport d’enquête enregistré. Tu peux joindre les photos et les autres preuves au dossier.');await openDetail(id);}});
function notice(message,error=false){$('notice').hidden=!message;$('notice').textContent=message;$('notice').className=error?'error':''}
async function api(path,body,options={}){const response=await fetch('/api/sst/'+path,{cache:'no-store',...options,...(body!==undefined?{method:'POST',headers:{'Content-Type':'application/json','X-SST-Request':'1',...options.headers},body:JSON.stringify(body)}:{})});let data;try{data=await response.json()}catch{throw Error('Réponse du serveur indisponible. Réessayez.')}if(!response.ok)throw Object.assign(Error(data.error||'Opération impossible.'),{status:response.status});return data}
const person=r=>state.employees.find(p=>p.key===r.employee_key)?.name||r.employee_name||'';
const department=id=>state.departments.find(d=>d.id===Number(id))?.name||'Tout le magasin';
const proofs=id=>state.documents.filter(d=>d.record_id===id&&!d.archived_at);
function eventProofs(id){const r=state.records.find(r=>r.id===id);const ids=r?.event_group_id?new Set(state.records.filter(x=>x.kind==='incident'&&x.event_group_id===r.event_group_id).map(x=>x.id)):new Set([id]);return state.documents.filter(d=>ids.has(d.record_id)&&!d.archived_at);}
const overdue=r=>!!r.due_date&&iso(r.due_date)<today()&&(r.status!=='done'||r.kind==='training');
const displayStatus=(kind,status)=>kind==='incident'&&status==='open'?'draft':status;
const pill=r=>`<span class="pill ${esc(r.status)}">${esc(statusLabels(r.kind)[displayStatus(r.kind,r.status)])}</span>`;
function activeRecords(){return state.records.filter(r=>!r.archived_at)}
function byActivityDate(a,b){const ad=iso(a.event_date),bd=iso(b.event_date);return bd.localeCompare(ad)||(a.title||a.name||'').localeCompare(b.title||b.name||'','fr-CA')}
function byDocumentDate(a,b){return byActivityDate({event_date:state.records.find(r=>r.id===a.record_id)?.event_date,title:a.name},{event_date:state.records.find(r=>r.id===b.record_id)?.event_date,title:b.name})}
function filteredRecords(kind){const q=$('search').value.trim().toLocaleLowerCase('fr-CA'),dept=$('departmentFilter').value,status=$('statusFilter').value,archived=$('archivedFilter').checked;return state.records.filter(r=>(!kind||r.kind===kind)&&Boolean(r.archived_at)===archived&&(!dept||String(r.department_id)===dept)&&(!status||(kind==='incident'?displayStatus(r.kind,r.status):r.status)===status)&&(!q||[r.title,person(r),r.owner,r.details,JSON.stringify(r.fields)].join(' ').toLocaleLowerCase('fr-CA').includes(q))).sort(byActivityDate)}
function recordTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Dossier</th><th>Employé / département</th><th>État</th><th>Responsable</th><th>Échéance</th><th>Preuves</th><th>Impression</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button type="button" class="table-button" data-record="${r.id}">${esc(r.title)}</button><small>${esc(kinds[r.kind].single)} · ${date(r.event_date)}</small></td><td>${esc(person(r)||'—')}<small>${esc(department(r.department_id))}</small></td><td>${pill(r)}${r.archived_at?'<small>Archivé</small>':''}</td><td>${esc(r.owner||'À attribuer')}</td><td class="${overdue(r)?'due':''}">${r.due_date?date(r.due_date):'—'}</td><td>${proofs(r.id).length} fichier(s)</td><td><button type="button" class="quiet" data-print-record="${r.id}" aria-label="Imprimer ${esc(r.title)}">Imprimer</button></td></tr>`).join('')}</tbody></table></div>`:empty('Aucun dossier pour cette sélection.','Crée un dossier, puis ajoute les preuves que tu possèdes déjà.')}
function empty(title,description=''){return `<div class="empty"><strong>${title}</strong>${description?'<p>'+description+'</p>':''}<button class="button secondary" type="button" data-new="${kinds[view]?view:'document'}">＋ Créer un dossier</button></div>`}
function dashboard(){const records=activeRecords(),late=records.filter(overdue),pending=records.filter(r=>r.status==='draft'),actions=records.filter(r=>r.kind==='action'&&r.status!=='done'),docs=state.documents.filter(d=>!d.archived_at);const recent=records.slice(0,6),latest=state.imports?.[0];return `${latest?`<section class="intake-banner"><div><strong>${latest.document_count} originaux classés et conservés</strong><p>${esc(latest.label)} · Les modèles vierges et les points à vérifier sont identifiés.</p></div>${latest.report_id?`<button class="button secondary" data-record="${latest.report_id}">Lire le bilan du classement →</button>`:''}</section>`:''}<div class="metrics"><article class="metric"><small>Employés au répertoire</small><strong>${state.employees.filter(p=>p.active).length}</strong><p>Fiches partagées avec les horaires</p></article><article class="metric"><small>Preuves conservées</small><strong>${docs.length}</strong><p>Documents originaux joints</p></article><article class="metric alert"><small>Échéances à traiter</small><strong>${late.length}</strong><p>Dates dépassées ou renouvellements</p></article><article class="metric"><small>Dossiers à compléter</small><strong>${pending.length}</strong><p>Informations encore en préparation</p></article></div><section class="inspection-banner"><div><p class="eyebrow">PRÉPARATION DE LA VISITE</p><h2>CNESST · Mardi 10 novembre 2026</h2><p>Un dossier pour réunir l’avis de visite, les documents disponibles et les suivis à réaliser.</p></div><button class="button" type="button" id="prepareVisit">Préparer le dossier →</button></section><div class="dashboard-grid"><section class="panel"><div class="section-title"><h2>Les prochaines étapes</h2><button class="quiet" data-view="action">Tous les correctifs</button></div>${[...late,...actions.filter(r=>!late.includes(r))].slice(0,6).map(r=>`<div class="mini-row"><div><button class="table-button" data-record="${r.id}">${esc(r.title)}</button><small>${esc(r.owner||'Responsable à attribuer')} · ${esc(department(r.department_id))}</small></div><span class="${overdue(r)?'due':''}">${r.due_date?date(r.due_date):'À planifier'}</span></div>`).join('')||'<p>Aucune échéance enregistrée. Les correctifs apparaîtront ici avec leur responsable et leur date de suivi.</p>'}</section><section class="panel"><h2>Commencer avec vos documents</h2><p>Les formations, les rencontres et les procédures peuvent être consignées avec leur vraie date, puis accompagnées des preuves disponibles.</p><div class="row-actions" style="margin-top:18px"><button class="button secondary" data-new="training">＋ Une formation</button><button class="button secondary" data-new="meeting">＋ Une rencontre</button><button class="quiet" id="trancheurTemplate">Documenter le trancheur</button></div></section></div><div class="topic-grid">${['training','equipment','incident','meeting','inspection','action'].map(k=>`<button class="topic" data-view="${k}"><span class="topic-icon">${kinds[k].icon}</span><b>${kinds[k].name}</b><p>${records.filter(r=>r.kind===k).length} dossier(s) · ${records.filter(r=>r.kind===k).reduce((n,r)=>n+proofs(r.id).length,0)} preuve(s)</p></button>`).join('')}</div><div class="section-title"><h2>Derniers dossiers mis à jour</h2></div>${recordTable(recent)}`}
function employeesView(){const q=$('search').value.toLocaleLowerCase('fr-CA'),dept=$('departmentFilter').value,people=state.employees.filter(p=>(!q||p.name.toLocaleLowerCase('fr-CA').includes(q))&&(!dept||p.departments.includes(Number(dept))));return `<p class="employee-source">Répertoire lu directement depuis les horaires. Les noms, le statut actif et les départements ne sont pas ressaisis dans la SST. Aucun code de connexion ni renseignement médical n’est importé ici.</p><div class="table-wrap"><table><thead><tr><th>Employé</th><th>Départements</th><th>Source</th><th>Formations consignées</th><th>Preuves</th><th>Impression</th></tr></thead><tbody>${people.map(p=>{const r=activeRecords().filter(r=>r.employee_key===p.key&&r.kind==='training');return `<tr><td><button class="table-button" data-person="${p.key}">${esc(p.name)}</button><small>${p.active?'Actif':'Inactif / départ'}${p.jobTitle?' · '+esc(p.jobTitle):''}</small></td><td>${p.departments.map(department).map(esc).join(', ')||'À préciser'}</td><td>${p.source}</td><td>${r.filter(r=>r.status==='done').length} réalisée(s) · ${r.filter(r=>r.status!=='done').length} à traiter</td><td>${r.reduce((n,r)=>n+proofs(r.id).length,0)} fichier(s)</td></tr>`}).join('')}</tbody></table></div>${!people.length?'<p class="hint">Aucun employé ne correspond à la recherche.</p>':''}${employeeKey?`<section class="employee-detail panel"><div class="section-title"><h2>Dossiers de ${esc(state.employees.find(p=>p.key===employeeKey)?.name||'cet employé')}</h2><button class="button secondary" data-training-person="${employeeKey}">＋ Consigner une formation</button></div>${recordTable(activeRecords().filter(r=>r.employee_key===employeeKey))}</section>`:''}`}
function documentsView(){const q=$('search').value.toLocaleLowerCase('fr-CA'),dept=$('departmentFilter').value,archived=$('archivedFilter').checked;const docs=state.documents.filter(d=>Boolean(d.archived_at)===archived&&(!q||(d.name+' '+(state.records.find(r=>r.id===d.record_id)?.title||'')).toLocaleLowerCase('fr-CA').includes(q))&&(!dept||String(state.records.find(r=>r.id===d.record_id)?.department_id)===dept)).sort(byDocumentDate);return docs.length?`<div class="table-wrap"><table><thead><tr><th>Document original</th><th>Dossier</th><th>Activité / événement</th><th>Empreinte SHA-256</th><th>Gestion</th></tr></thead><tbody>${docs.map(d=>`<tr><td><a href="/sst#file=${d.id}" target="_blank" rel="noopener">${esc(d.name)}</a><small>${bytes(d.size)}${d.archived_at?' · archivé':''}</small></td><td>${d.record_id?`<button class="table-button" data-record="${d.record_id}">${esc(state.records.find(r=>r.id===d.record_id)?.title||'Dossier')}</button>`:'Bibliothèque générale'}</td><td>${date(state.records.find(r=>r.id===d.record_id)?.event_date)}<details><summary>Historique administratif</summary><small>Ajouté le ${stamp(d.created_at)}</small></details></td><td><small title="${d.sha256}">${d.sha256.slice(0,14)}…</small></td><td><button class="quiet" data-file-archive="${d.id}">${d.archived_at?'Restaurer':'Archiver'}</button><details><summary>Changer de dossier</summary><label>Dossier de destination<select id="move-${d.id}">${activeRecords().map(r=>`<option value="${r.id}" ${r.id===d.record_id?'selected':''}>${esc(r.title)}</option>`).join('')}</select></label><button class="quiet" data-file-move="${d.id}">Enregistrer le rattachement</button></details></td></tr>`).join('')}</tbody></table></div>`:empty('Aucune preuve pour cette sélection.','Utilise « Ajouter une preuve » pour conserver un original et le rattacher à un dossier.')}
function sobeysRecords(){return filteredRecords('document').filter(r=>/^Sobeys · /i.test(r.title))}
function sourceLink(r){try{const u=new URL(r.fields.reference);return u.protocol==='https:'&&u.hostname==='sobeys.ecm.telussante.com'?'<a class="button secondary" href="'+esc(u.href)+'" target="_blank" rel="noopener noreferrer">Consulter la source Sobeys ↗</a>':''}catch{return ''}}
function sobeysView(){return '<p class="hint">Modèles et supports de prévention à utiliser et à adapter au magasin. Les liens sources nécessitent votre connexion Sobeys.</p>'+sobeysRecords().map(r=>'<section class="panel" style="margin-bottom:14px"><h2><button class="table-button" data-record="'+r.id+'">'+esc(r.title.replace(/^Sobeys · /,''))+'</button></h2><p>'+esc(r.fields.procedure||'')+'</p><div class="row-actions">'+sourceLink(r)+'<button class="quiet" data-record="'+r.id+'">'+(proofs(r.id).length?'Lire la copie conservée':'Voir la fiche')+'</button></div></section>').join('')}
function preventionRecords(){return filteredRecords('document').filter(r=>/\bprogramme de pr[eé]vention\b/i.test(r.title))}
let preventionChoice='';
function preventionView(){const records=activeRecords().filter(r=>r.kind==='document'&&/programme de pr[eé]vention/i.test(r.title)).sort((a,b)=>Number(/^Archives/i.test(a.title))-Number(/^Archives/i.test(b.title))||b.title.localeCompare(a.title,'fr',{numeric:true}));const files=records.flatMap(r=>proofs(r.id).map(d=>({...d,label:r.title+' · '+d.name})));if(!files.length)return empty('Aucun programme joint.','Ajoute le programme original pour le consulter directement ici.');if(!files.some(d=>d.id===preventionChoice))preventionChoice=files[0].id;return '<section class="panel"><label>Version du programme<select id="preventionVersion">'+files.map(d=>'<option value="'+d.id+'" '+(d.id===preventionChoice?'selected':'')+'>'+esc(d.label)+'</option>').join('')+'</select></label><div id="preventionDocument" style="margin-top:18px"></div></section>';}
function mountPrevention(){const select=$('preventionVersion');if(!select)return;const show=()=>{preventionChoice=select.value;const container=$('preventionDocument');container.replaceChildren();const reader=document.createElement('div');container.append(reader);displayDocument(reader,state.documents.find(d=>d.id===select.value));};select.onchange=()=>{if(!preventionEditor.canLeave()){select.value=preventionChoice;return;}show();};show();}
let meetingYear=Number(today().slice(0,4));
function meetingView(){calendarStyles();const rows=filteredRecords('meeting'),undated=rows.filter(r=>!meetingDate(r));return '<div id="meetingCalendar">'+calendarHTML(rows,meetingYear,today())+'</div>'+(undated.length?'<section class="mc-undated"><h2>Dates à préciser · '+undated.length+'</h2>'+recordTable(undated)+'</section>':'')+'<details class="mc-list"><summary>Liste des rencontres de '+meetingYear+'</summary>'+recordTable(rows.filter(r=>meetingDate(r).startsWith(meetingYear+'-')))+'</details>';}
function printMeetingCalendar(){const target=$('sstPrint');target.innerHTML='<h1>Comité et rencontres · '+meetingYear+'</h1><p>IGA Extra Famille Benoit · '+esc(department($('departmentFilter').value))+'</p>';for(const selector of ['.mc-legend','.mc-year','.mc-undated']){const source=$('content').querySelector(selector);if(source)target.append(source.cloneNode(true));}for(const actions of target.querySelectorAll('.mc-event-actions'))actions.remove();for(const b of target.querySelectorAll('button')){const text=document.createElement('span');text.className=b.className;text.innerHTML=b.innerHTML;b.replaceWith(text);}window.print();}
function taskAnalysisRecords(){return filteredRecords('document').filter(r=>/^analyse des t[aâ]ches\b/i.test(r.title))}
function render(){if(!$('workspace').hidden){$('newButton').hidden=['inspection_grid','equipment_training'].includes(view);$('uploadButton').hidden=['inspection_grid','equipment_training'].includes(view);const selectedStatus=$('statusFilter').value;const filterLabels=view==='incident'?statusLabels('incident'):view==='prevention'?statusLabels('document'):{draft:'À compléter',open:'Prévu / ouvert / en service',progress:'En cours / à vérifier',done:'Réalisé / fermé / hors service'};$('statusFilter').innerHTML='<option value="">Tous les états</option>'+Object.entries(filterLabels).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('');$('statusFilter').value=Object.hasOwn(filterLabels,selectedStatus)?selectedStatus:'';$('viewTitle').textContent=views[view][0];$('viewEyebrow').textContent=views[view][1];$('viewDescription').textContent=views[view][2];$('navigation').innerHTML=Object.entries(views).map(([k,v])=>`<button type="button" class="${k===view?'active':''}" aria-current="${k===view?'page':'false'}" data-view="${k}"><span class="nav-icon">${v[3]}</span>${v[0]}</button>`).join('');$('filters').hidden=['dashboard','journal','inspection_grid','equipment_training','prevention'].includes(view);$('statusFilter').closest('label').hidden=['employees','documents'].includes(view);$('archivedFilter').closest('label').hidden=view==='employees';$('newButton').textContent=view==='incident'?'＋ Nouveau rapport d’enquête':view==='prevention'?'＋ Programme de prévention':view==='task_analysis'?'＋ Analyse des tâches':kinds[view]?'＋ '+kinds[view].single:'＋ Nouveau dossier';$('content').innerHTML=view==='equipment_training'?'<div id="equipmentTraining"></div>':view==='inspection_grid'?'<div id="inspectionGrid"></div>':view==='dashboard'?dashboard():view==='employees'?employeesView():view==='sobeys'?sobeysView():view==='prevention'?preventionView():view==='meeting'?meetingView():view==='task_analysis'?recordTable(taskAnalysisRecords()):view==='documents'?documentsView():view==='training'?'<p><button class="button primary" data-welcome-form>＋ Accueil général SST · Annexe 11.1</button></p>'+recordTable(filteredRecords('training')):view==='incident'?incidentOrganisation.render(filteredRecords('incident')):view==='journal'?'<p><a class="button secondary" href="/api/sst/audit-export" download>Télécharger l’historique des saisies</a></p><div id="globalJournal" class="panel">Chargement du journal…</div>':recordTable(filteredRecords(view));if(view==='prevention')mountPrevention();if(view==='equipment_training')equipmentTraining.mount($('equipmentTraining'));if(view==='inspection_grid')inspectionGrid.mount($('inspectionGrid'));if(view==='journal')loadJournal();}}
function lockScreen(message){welcomeForm.clear();incidentOrganisation.clear();incidentReport.clear();preventionEditor.clear();equipmentTraining.clear();inspectionGrid.clear();state={records:[],documents:[],employees:[],departments:[]};editing=null;detailId=null;for(const d of document.querySelectorAll('dialog[open]'))d.close();$('recordForm').reset();$('uploadForm').reset();$('importForm').reset();$('importPreview').replaceChildren();$('detailContent').replaceChildren();$('content').replaceChildren();$('sstPrint').replaceChildren();$('workspace').hidden=true;$('locked').hidden=false;$('lockedMessage').textContent=message;}
