function openEditor(kind='document',record=null,preset={}){if(record?.fields?.welcomeForm){welcomeForm.open(record);return;}if(kind==='incident'&&(record?.fields?.accidentReport||(!record&&!Object.keys(preset).length))){incidentReport.open(record);return;}if(!kinds[kind])kind='document';editing=record;$('recordForm').reset();$('recordError').textContent='';$('recordKind').innerHTML=Object.entries(kinds).map(([k,v])=>`<option value="${k}">${v.single}</option>`).join('');$('recordKind').value=kind;$('recordKind').disabled=!!record;fillSpecific(kind,record?.fields||preset.fields||{});$('recordStatus').value=displayStatus(kind,record?.status||preset.status||'draft');$('recordTitle').value=record?.title||preset.title||'';$('recordDepartment').innerHTML='<option value="">Tout le magasin</option>'+state.departments.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('');$('recordDepartment').value=record?.department_id||preset.departmentId||'';
 $('recordEmployee').innerHTML='<option value="">Aucun employé précis</option>'+state.employees.map(p=>`<option value="${p.key}">${esc(p.name)}${p.active?'':' · inactif'}</option>`).join('');$('recordEmployee').value=record?.employee_key||preset.employeeKey||'';$('recordRelated').innerHTML='<option value="">Aucun dossier lié</option>'+activeRecords().filter(r=>r.id!==record?.id).map(r=>`<option value="${r.id}">${esc(r.title)}</option>`).join('');$('recordRelated').value=record?.related_id||preset.relatedId||'';$('recordDate').value=iso(record?.event_date||preset.eventDate);$('recordDue').value=iso(record?.due_date||preset.dueDate);$('recordOwner').value=record?.owner||preset.owner||'';$('recordDetails').value=record?.details||preset.details||'';$('editorTitle').textContent=(record?'Modifier · ':'Nouveau · ')+kinds[kind].single;if(!$('recordDialog').open)$('recordDialog').showModal()}
function formData(){const kind=$('recordKind').value;return {...(editing?{id:editing.id,version:editing.version}:{}),kind,status:$('recordStatus').value,title:$('recordTitle').value,employeeKey:$('recordEmployee').value||null,departmentId:$('recordDepartment').value?Number($('recordDepartment').value):null,relatedId:$('recordRelated').value||null,eventDate:$('recordDate').value||null,dueDate:$('recordDue').value||null,owner:$('recordOwner').value,details:$('recordDetails').value,fields:Object.fromEntries(kinds[kind].fields.map(([key])=>[key,$('field-'+key).value]))}}
