function detailFields(r){return `<div class="detail-grid">${[['Type',kinds[r.kind].single],['Statut',statusLabels(r.kind)[displayStatus(r.kind,r.status)]],['Département',department(r.department_id)],['Employé',person(r)||'Aucun employé précis'],['Date de l’activité',date(r.event_date)],['Échéance',r.due_date?date(r.due_date):'—'],['Responsable',r.owner||'À attribuer'],['Dossier lié',state.records.find(x=>x.id===r.related_id)?.title||'—']].map(([k,v])=>`<div class="detail-field"><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</div>${kinds[r.kind].fields.filter(([key])=>r.fields[key]).map(([key,label])=>`<h3>${label}</h3><p class="details-text">${esc(r.fields[key])}</p>`).join('')}${r.details?'<h3>Notes et contexte</h3><p class="details-text">'+esc(r.details)+'</p>':''}`}
