const eventLabel=action=>({'incident.grouped':'Fiches regroupées dans un événement','incident.ungrouped':'Fiches dissociées','incident.followup.updated':'État et responsable mis à jour','record.created':'Dossier créé','record.updated':'Dossier corrigé','record.archived':'Dossier archivé','record.restored':'Dossier restauré','document.moved':'Rattachement de la preuve corrigé','document.added':'Preuve originale ajoutée','document.archived':'Preuve archivée','document.restored':'Preuve restaurée'}[action]||action);
function originalPreview(id){const files=eventProofs(id);if(!files.length)return '<p class="hint">Aucun document original joint. Ajoute une preuve pour la consulter ici.</p>';return '<section class="original-reader"><label>Document à consulter<select id="originalChoice">'+files.map(d=>'<option value="'+d.id+'">'+esc(d.name)+'</option>').join('')+'</select></label><div id="originalCanvas"></div></section>'}
async function showOriginal(id){const d=state.documents.find(d=>d.id===id),host=$('originalCanvas');if(!d||!host)return;const url='/api/sst/documents/'+d.id;const pdf=d.mime==='application/pdf'||/\.pdf$/i.test(d.name),img=/^image\/(png|jpeg|gif|webp)$/.test(d.mime);host.innerHTML='<div class="reader-actions"><button class="button secondary" data-download-original="'+d.id+'">Télécharger le document original</button></div>'+(pdf?'<div id="pdfReader" class="original-image" style="height:70dvh"><p>Chargement du document…</p></div>':img?'<div class="original-image"><img src="'+url+'" alt="'+esc(d.name)+'"></div>':'<div class="original-unavailable"><h3>'+esc(d.name)+'</h3><p>Télécharge le document pour l’ouvrir dans son application et conserver sa mise en page.</p></div>');if(pdf)await renderOriginalPDF(url,id)}

let pdfReadSequence=0,pdfReadTask=null;
async function renderOriginalPDF(url,id){
 const seq=++pdfReadSequence,host=$('pdfReader');if(pdfReadTask){await pdfReadTask.destroy();pdfReadTask=null}
 try{
 const lib=await import('/vendor/pdfjs/pdf.min.mjs');
 if(seq!==pdfReadSequence||$('originalChoice')?.value!==id)return;
 lib.GlobalWorkerOptions.workerSrc='/vendor/pdfjs/pdf.worker.min.mjs';
 const task=lib.getDocument({url,isEvalSupported:false});pdfReadTask=task;const pdf=await task.promise;
 if(seq!==pdfReadSequence||!host.isConnected||$('originalChoice')?.value!==id){await task.destroy();return}
 host.innerHTML='<div class="row-actions" style="justify-content:center;position:sticky;top:0;background:#f3f5f1;padding:8px"><button class="quiet" id="pdfPrev">← Page précédente</button><span id="pdfPageLabel"></span><button class="quiet" id="pdfNext">Page suivante →</button></div><canvas style="display:block;max-width:100%;height:auto;margin:16px auto;background:white"></canvas>';
 let pageNumber=1,busy=false;
 const draw=async()=>{if(busy)return;busy=true;const prev=host.querySelector('#pdfPrev'),next=host.querySelector('#pdfNext');prev.disabled=next.disabled=true;try{const page=await pdf.getPage(pageNumber);if(!host.isConnected)return;const viewport=page.getViewport({scale:1.6}),canvas=host.querySelector('canvas');canvas.width=viewport.width;canvas.height=viewport.height;canvas.setAttribute('aria-label','Page '+pageNumber+' du document');await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;host.querySelector('#pdfPageLabel').textContent='Page '+pageNumber+' / '+pdf.numPages;host.scrollTop=0}finally{busy=false;prev.disabled=pageNumber===1;next.disabled=pageNumber===pdf.numPages}};
 host.querySelector('#pdfPrev').onclick=()=>{if(!busy&&pageNumber>1){pageNumber--;draw().catch(()=>notice('Impossible d’afficher cette page.',true))}};
 host.querySelector('#pdfNext').onclick=()=>{if(!busy&&pageNumber<pdf.numPages){pageNumber++;draw().catch(()=>notice('Impossible d’afficher cette page.',true))}};
 await draw();
 }catch(e){if(host.isConnected&&seq===pdfReadSequence)host.innerHTML='<p>Impossible de charger l’aperçu. Utilise « Ouvrir le document original ».</p>'}
}
async function openDetail(id){const r=state.records.find(r=>r.id===id);if(!r)return;if(r.fields?.welcomeForm){welcomeForm.open(r);return;}if(r.fields?.employeeFileOriginalId){detailId=id;$('detailTitle').textContent=r.title;$('detailContent').innerHTML='<p>Original partagé avec le dossier employé. Les corrections se font dans ce dossier.</p><a class="button secondary" href="/dossiers-employes">Ouvrir les dossiers employés</a>'+originalPreview(r.id);if(!$('detailDialog').open)$('detailDialog').showModal();const files=eventProofs(id);if(files.length){$('originalChoice').value=files[0].id;$('originalChoice').onchange=e=>showOriginal(e.target.value);await showOriginal(files[0].id);}return;}detailId=id;const turn=++detailSequence;$('detailTitle').textContent=r.title;$('detailContent').innerHTML=`<div class="row-actions">${r.archived_at?`<button class="button secondary" data-record-archive="${r.id}">Restaurer le dossier</button>`:`<button class="button primary" data-edit="${r.id}">Modifier</button><button class="button secondary" data-upload="${r.id}">＋ Ajouter une preuve</button><button class="quiet" data-new-linked="${r.id}">＋ Un correctif lié</button><button class="quiet" data-record-archive="${r.id}">Archiver</button>`}<button class="quiet" data-print-record="${r.id}">Imprimer le dossier</button></div>${sourceLink(r)}${incidentOrganisation.groupSummary(r)}${r.kind==='incident'?`<div class="row-actions" style="margin-top:16px">${!r.archived_at?`<button class="button secondary" data-incident-report="${r.id}">${r.fields?.accidentReport?'Modifier le rapport d’enquête':'Remplir le rapport d’enquête · Annexe 3.1'}</button>`:''}${r.fields?.accidentReport?`<button class="button secondary" data-print-incident="${r.id}">Imprimer le formulaire</button>`:''}</div>`:''}${r.fields?.accidentReport?incidentReport.preview(r):''}${originalPreview(r.id)}<details class="record-information"><summary>Informations, notes et suivi du dossier</summary>${detailFields(r)}<h3>Preuves originales (${eventProofs(r.id).length})</h3>${eventProofs(r.id).map(d=>`<div class="detail-proof"><div><a href="/sst#file=${d.id}" target="_blank" rel="noopener">${esc(d.name)}</a><p class="hint">${bytes(d.size)} · SHA-256 ${d.sha256.slice(0,16)}…</p></div><button class="quiet" data-file-archive="${d.id}">Archiver</button></div>`).join('')||'<p class="hint">Aucune preuve jointe à ce dossier. Les notes saisies ne sont pas un document original.</p>'}<h3 style="margin-top:22px">Dossiers liés</h3>${recordTable(activeRecords().filter(x=>x.related_id===id))}<details style="margin-top:22px"><summary>Historique administratif</summary><p class="hint">Les dates de saisie sont distinctes des dates des activités.</p><p class="hint">Créé le ${stamp(r.created_at)} · dernière saisie le ${stamp(r.updated_at)} · version ${r.version}.</p><div id="recordHistory">Chargement…</div></details></details>`;if($('originalChoice')){$('originalChoice').onchange=e=>showOriginal(e.target.value);const preferred=eventProofs(id).find(d=>/\.pdf$/i.test(d.name))||eventProofs(id)[0];$('originalChoice').value=preferred.id;showOriginal(preferred.id)}if(!$('detailDialog').open)$('detailDialog').showModal();try{const {events}=await api('history?id='+id);if(turn===detailSequence&&$('recordHistory'))$('recordHistory').innerHTML=eventHTML(events)}catch(e){if(turn===detailSequence&&$('recordHistory'))$('recordHistory').textContent=e.message}}
async function loadJournal(){try{const {events}=await api('history');if(view==='journal'&&$('globalJournal'))$('globalJournal').innerHTML=events.length?eventHTML(events):'<p>Aucune opération enregistrée. Les premières saisies apparaîtront ici.</p>'}catch(e){if($('globalJournal'))$('globalJournal').textContent=e.message}}
function openUpload(id=null){$('uploadForm').reset();$('uploadError').textContent='';$('uploadRecord').innerHTML='<option value="">Bibliothèque générale · aucun dossier</option>'+activeRecords().map(r=>`<option value="${r.id}">${esc(r.title)}</option>`).join('');$('uploadRecord').value=id||'';if(!$('uploadDialog').open)$('uploadDialog').showModal()}
$('uploadForm').onsubmit=async e=>{e.preventDefault();const file=$('proofFile').files[0];if(!file)return;if(file.size>12*1024*1024){$('uploadError').textContent='Le fichier dépasse 12 Mo.';return}$('uploadFields').disabled=true;try{const recordId=$('uploadRecord').value;const res=await fetch('/api/sst/documents'+(recordId?'?recordId='+recordId:''),{method:'POST',headers:{'Content-Type':'application/octet-stream','X-SST-Request':'1','X-Filename':encodeURIComponent(file.name)},body:file});const data=await res.json();if(!res.ok)throw Error(data.error||'Ajout non confirmé.');$('uploadDialog').close();await load();notice('Preuve conservée. Le fichier original et son empreinte sont enregistrés.');if(recordId)await openDetail(recordId)}catch(e){$('uploadError').textContent=e.message}finally{$('uploadFields').disabled=false}};
