function printBody(rows,title){return `<header><h1>Santé et sécurité · IGA Famille Benoit</h1><p>${esc(title)}</p></header>${rows.map(r=>r.fields?.welcomeForm?welcomeForm.preview(r):`<section><h2>${esc(r.title)}</h2><p><strong>${kinds[r.kind].single}</strong> · ${statusLabels(r.kind)[displayStatus(r.kind,r.status)]}</p><p>Département : ${esc(department(r.department_id))} · Employé : ${esc(person(r)||'—')}</p><p>Activité / événement : ${date(r.event_date)} · Échéance : ${r.due_date?date(r.due_date):'—'}</p><p>Responsable : ${esc(r.owner||'À attribuer')}</p>${kinds[r.kind].fields.filter(([key])=>r.fields[key]).map(([key,label])=>`<div class="print-field"><h3>${label}</h3><p>${esc(r.fields[key])}</p></div>`).join('')}${r.details?'<div class="print-field"><h3>Notes et contexte</h3><p>'+esc(r.details)+'</p></div>':''}${r.fields?.accidentReport?incidentReport.preview(r):''}<h3>Index des preuves originales · ${proofs(r.id).length} fichier(s)</h3>${proofs(r.id).length?`<table><thead><tr><th>Document</th></tr></thead><tbody>${proofs(r.id).map(d=>`<tr><td>${esc(d.name)}</td></tr>`).join('')}</tbody></table>`:'<p>Aucune preuve originale jointe.</p>'}</section>`).join('')}`}
