function printRecord(id){const r=state.records.find(r=>r.id===id);if(!r)return;if(r.fields?.welcomeForm){welcomeForm.printRecord(r);return;}const included=r.event_group_id?state.records.filter(x=>x.kind==='incident'&&x.event_group_id===r.event_group_id):[r],seen=new Set(included.map(x=>x.id));for(let n=0;n<included.length;n++)for(const child of activeRecords())if(child.related_id===included[n].id&&!seen.has(child.id)){seen.add(child.id);included.push(child)}printRecords(included,'Dossier et suivis liés')}
$('printList').onclick=()=>{if(view==='incident'){printRecords(incidentOrganisation.selectedRecords(),'Événements et pièces regroupées');return;}if(view==='meeting'){printRecords(filteredRecords('meeting').filter(r=>meetingDate(r).startsWith(meetingYear+'-')),'Rencontres SST · '+meetingYear);return;}if(view==='documents'){const q=$('search').value.toLocaleLowerCase('fr-CA'),dept=$('departmentFilter').value;const docs=state.documents.filter(d=>Boolean(d.archived_at)===$('archivedFilter').checked&&(!q||(d.name+' '+(state.records.find(r=>r.id===d.record_id)?.title||'')).toLocaleLowerCase('fr-CA').includes(q))&&(!dept||String(state.records.find(r=>r.id===d.record_id)?.department_id)===dept)).sort(byDocumentDate);$('sstPrint').innerHTML='<h1>Bibliothèque des preuves SST</h1><table><thead><tr><th>Document</th><th>Dossier</th></tr></thead><tbody>'+docs.map(d=>`<tr><td>${esc(d.name)}</td><td>${esc(state.records.find(r=>r.id===d.record_id)?.title||'Bibliothèque générale')}</td></tr>`).join('')+'</tbody></table>';window.print();return}printRecords(view==='prevention'?preventionRecords():view==='sobeys'?sobeysRecords():view==='task_analysis'?taskAnalysisRecords():view==='employees'&&employeeKey?activeRecords().filter(r=>r.employee_key===employeeKey):filteredRecords(kinds[view]?view:null),views[view][0])};
$('refresh').onclick=async()=>{if(view==='prevention'&&!preventionEditor.canLeave())return;if(view==='equipment_training'&&!equipmentTraining.canLeave())return;if(view==='inspection_grid'&&!inspectionGrid.canLeave())return;await load();notice('Répertoire et dossiers actualisés.');if($('detailDialog').open&&detailId)await openDetail(detailId)};
