for(const id of ['search','departmentFilter','statusFilter','archivedFilter'])$(id).addEventListener('input',render);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(Object.hasOwn(d,'welcomeForm')){welcomeForm.open();return;}if(Object.hasOwn(d,'incidentReport')){const r=state.records.find(r=>r.id===d.incidentReport);if(r&&!r.archived_at){$('detailDialog').close();incidentReport.open(r);}return;}if(Object.hasOwn(d,'printIncident')){const r=state.records.find(r=>r.id===d.printIncident);if(r)incidentReport.printRecord(r);return;}if(Object.hasOwn(d,'calendarYear')){const year=Number(d.calendarYear);if(year>=1900&&year<=2200){meetingYear=year;render();}return;}if(Object.hasOwn(d,'calendarPrint')){printMeetingCalendar();return;}if(Object.hasOwn(d,'meetingDate')){openEditor('meeting',null,{title:'Rencontre SST',status:'open',eventDate:d.meetingDate,departmentId:$('departmentFilter').value||null});return;}if(Object.hasOwn(d,'meetingEdit')){const r=state.records.find(r=>r.id===d.meetingEdit);if(r)openEditor('meeting',r);return;}if(Object.hasOwn(d,'downloadOriginal')){downloadOriginal(d.downloadOriginal,b);return}if(Object.hasOwn(d,'close')){$(d.close).close();return}if(Object.hasOwn(d,'view')){switchView(d.view);return}if(Object.hasOwn(d,'record')){openDetail(d.record);return}if(Object.hasOwn(d,'new')){openEditor(d.new);return}if(Object.hasOwn(d,'edit')){$('detailDialog').close();const r=state.records.find(r=>r.id===d.edit);openEditor(r.kind,r);return}if(Object.hasOwn(d,'upload')){openUpload(d.upload);return}if(Object.hasOwn(d,'recordArchive')){archiveRecord(d.recordArchive);return}if(Object.hasOwn(d,'fileMove')){const file=state.documents.find(f=>f.id===d.fileMove),recordId=$('move-'+d.fileMove).value;b.disabled=true;api('documents/'+file.id+'/move',{version:file.version,recordId}).then(load).then(()=>notice('Rattachement corrigé.')).catch(e=>{notice(e.message,true);b.disabled=false});return}if(Object.hasOwn(d,'fileArchive')){archiveDocument(d.fileArchive);return}if(Object.hasOwn(d,'printRecord')){printRecord(d.printRecord);return}if(Object.hasOwn(d,'newLinked')){$('detailDialog').close();openEditor('action',null,{relatedId:d.newLinked});return}if(Object.hasOwn(d,'person')){employeeKey=d.person;render();document.querySelector('.employee-detail')?.scrollIntoView({behavior:'smooth'});return}if(Object.hasOwn(d,'trainingPerson')){openEditor('training',null,{employeeKey:d.trainingPerson});return}if(b.id==='prepareVisit'){const existing=activeRecords().find(r=>r.kind==='inspection'&&r.title.includes('CNESST')&&iso(r.event_date)==='2026-11-10');if(existing){openDetail(existing.id);return}openEditor('inspection',null,{title:'Visite CNESST · 10 novembre 2026',status:'open',eventDate:'2026-11-10',dueDate:'2026-11-09',fields:{location:'Magasin · préparation de la visite CNESST',findings:'À réunir selon l’avis de visite : rapport d’événement et enquête; manuel et procédures applicables au trancheur; formations et vérifications consignées; entretien et inspections; rencontres et correctifs.'},details:'Dossier de préparation. Les pièces disponibles sont à joindre; les éléments manquants restent à compléter. Aucun constat de l’inspection n’est encore consigné.'});return}if(b.id==='trancheurTemplate'){const dep=state.departments.find(d=>/charcut/i.test(d.name));openEditor('incident',null,{title:'Trancheur automatique · coupure en charcuterie',departmentId:dep?.id,fields:{location:'Charcuterie · trancheur automatique',reportedFacts:'La direction rapporte une mauvaise utilisation de l’appareil et indique que l’employée l’a reconnue. Déclaration à documenter dans le dossier.',analysis:'À compléter après examen des faits et des vérifications.'},details:'Brouillon de saisie à compléter : date de l’événement, employée, déclarations, vérifications et mesures prises. Aucune conclusion technique n’est établie par ce brouillon.'});return}});

async function downloadOriginal(id,button){
 const d=state.documents.find(x=>x.id===id);if(!d)return;
 button.disabled=true;
 try{const response=await fetch('/api/sst/documents/'+id,{credentials:'same-origin',cache:'no-store'});
 if(!response.ok){if(response.status===401||response.status===403){await load();throw Error('La session a expiré. Reconnecte-toi au portail pour télécharger le document.')}throw Error('Téléchargement indisponible. Réessaie.')}
 const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=d.name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
 }catch(e){notice(e.message,true)}finally{button.disabled=false}
}
async function openLinkedFile(){
 const match=/^#file=([a-f0-9-]{36})$/i.exec(location.hash);if(!match||$('workspace').hidden)return;
 const d=state.documents.find(x=>x.id===match[1]);if(!d){notice('Document introuvable dans les fichiers accessibles.',true);return}
 if(d.record_id){await openDetail(d.record_id);if($('originalChoice')){$('originalChoice').value=d.id;await showOriginal(d.id)}}
 else{detailId=null;$('detailTitle').textContent=d.name;$('detailContent').innerHTML='<section class="original-reader"><select id="originalChoice" aria-label="Document à consulter"><option value="'+d.id+'">'+esc(d.name)+'</option></select><div id="originalCanvas"></div></section>';$('detailDialog').showModal();await showOriginal(d.id)}
}
window.addEventListener('hashchange',openLinkedFile);

const initial=location.hash.slice(1);if(views[initial])view=initial;load().then(openLinkedFile);

let accessChecking=false;async function checkAccess(){if(accessChecking||document.hidden||$('workspace').hidden)return;accessChecking=true;try{await api('access')}catch(e){if(e.status===401||e.status===403)lockScreen(e.message)}finally{accessChecking=false}}setInterval(checkAccess,10000);window.addEventListener('focus',checkAccess);document.addEventListener('visibilitychange',checkAccess);

let importSequence=0;
$('importButton').onclick=()=>{if($('workspace').hidden){notice('Connecte-toi avec ton accès administrateur avant d’importer.',true);return}$('importDialog').showModal()};
$('importDialog').addEventListener('close',()=>{importSequence++;$('importForm').reset();$('importPreview').replaceChildren();$('importError').textContent='';$('importSubmit').disabled=true});
$('intakeFile').addEventListener('change',async()=>{const sequence=++importSequence,file=$('intakeFile').files[0];$('importSubmit').disabled=true;$('importError').textContent='';$('importPreview').replaceChildren();if(!file)return;try{if(file.size>16*1024*1024)throw Error('Le fichier dépasse 16 Mo.');const pack=JSON.parse(await file.text());if(sequence!==importSequence)return;if(pack.format!=='iga-sst-intake-v1'||!Array.isArray(pack.records)||!Array.isArray(pack.documents)||pack.records.length>100||pack.documents.length>100)throw Error('Ce fichier n’est pas un lot de classement SST reconnu.');$('importPreview').innerHTML=`<div class="hint"><strong>${pack.documents.length} fichiers originaux · ${pack.records.length} dossiers et suivis proposés</strong><p>${esc(pack.label)}</p><p>Les formulaires vierges, les événements historiques et les points à vérifier restent identifiés. Aucun dossier employé ni formation individuelle n’est créé automatiquement. Un lot déjà reçu n’est pas importé deux fois.</p></div><details><summary>Voir le classement avant l’import</summary><ul>${pack.records.map(r=>`<li>${esc(r.title)}</li>`).join('')}</ul></details>`;$('importSubmit').disabled=false}catch(e){if(sequence===importSequence)$('importError').textContent=e instanceof SyntaxError?'Le fichier JSON est illisible. Choisis le fichier de classement préparé.':e.message}});
$('importForm').addEventListener('submit',async e=>{e.preventDefault();const file=$('intakeFile').files[0];if(!file||$('importSubmit').disabled)return;$('importFields').disabled=true;$('importError').textContent='';try{const response=await fetch('/api/sst/import',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-SST-Request':'1'},body:file});const result=await response.json();if(!response.ok)throw Object.assign(Error(result.error||'L’import n’a pas été effectué.'),{status:response.status});$('importDialog').close();await load();notice(result.alreadyImported?'Ce lot avait déjà été importé. Les dossiers existants sont conservés.':`${result.documents} fichiers originaux importés et classés.`);if(result.reportId)await openDetail(result.reportId)}catch(e){if(e.status===401||e.status===403)lockScreen(e.message);else $('importError').textContent=e.message}finally{$('importFields').disabled=false}});


